// In case focus escapes the trap for some strange reason, pull it back in.
const checkFocusIn = function (e) {
  const target = getActualTarget(e);
  const targetContained = findContainerIndex(target, e) >= 0;

  // In Firefox when you Tab out of an iframe the Document is briefly focused.
  if (targetContained || target instanceof Document) {
    if (targetContained) {
      state.mostRecentlyFocusedNode = target;
    }
  } else {
    // escaped! pull it back in to where it just left
    e.stopImmediatePropagation();
    // Update tabbable nodes in case the DOM changed (e.g., focused node removed)
    updateTabbableNodes();
    // Determine the node to focus: prefer the most recently focused node if still in a container,
    // otherwise fall back to the first tabbable node in the first tabbable group.
    let nodeToFocus = null;
    if (state.mostRecentlyFocusedNode && state.containers.some(container => container.contains(state.mostRecentlyFocusedNode))) {
      nodeToFocus = state.mostRecentlyFocusedNode;
    } else if (state.tabbableGroups.length > 0 && state.tabbableGroups[0].firstTabbableNode) {
      nodeToFocus = state.tabbableGroups[0].firstTabbableNode;
    } else {
      nodeToFocus = getInitialFocusNode();
    }
    tryFocus(nodeToFocus);
  }
};
